// 清洗：把各种来源的字段统一
// 注意：返回对象的【顶层】字段值如果长得像表达式，n8n 会再求值一次，可能被污染
// 所以这里统一塞进一个 payload 里，下游只读 payload.xxx
const raw = $input.first().json.body ?? $input.first().json;
const txt = s => String(s ?? '').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,4000);
const email = String(raw.email ?? raw.contact_email ?? '').toLowerCase().match(/[\w.+-]+@[\w-]+\.[\w.-]+/)?.[0] ?? '';
const phone = String(raw.phone ?? raw.contact_phone ?? '').replace(/\D/g,'').replace(/^86(?=\d{11}$)/,'');
return [{ json: { payload: {
  source: String(raw.source ?? 'unknown').toLowerCase(),
  contact_name: txt(raw.name ?? raw.contact_name),
  contact_email: email,
  contact_phone: phone,
  message: txt(raw.message ?? raw.content ?? raw.body),
  budget_raw: raw.budget ?? null,
  raw_payload: JSON.stringify(raw)
}} }];

// 去重 + 分流：算指纹、查重、给出显式开关 route，不让 n8n 自己"猜"走哪条边
// 逐字段赋值，避免顶层字段值被 n8n 二次当成表达式求值
const hash = s => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0).toString(16).padStart(8, '0'); };

const store = $getWorkflowStaticData('global');
if (!store.seen) store.seen = {};
const now = Date.now(), TTL = 7 * 24 * 3600 * 1000;
for (const k of Object.keys(store.seen)) if (now - store.seen[k] > TTL) delete store.seen[k];

const p = $input.first().json.payload;
const key = (p.contact_email || p.contact_phone || '') + '|' + (p.message || '').replace(/\s+/g, '').toLowerCase();
const fp = hash(key);
const isDup = Object.prototype.hasOwnProperty.call(store.seen, fp);
if (!isDup) store.seen[fp] = now;

const out = { payload: p };
out.fingerprint = String(fp);
out.route = isDup ? 'dup' : 'new';
return [{ json: out }];

// 打分：纯规则，零成本、可解释、可复现。规则都写成数组，客户能自己改
const j = $input.first().json;
const p = j.payload;
// 字段名各家表单都不一样：显式取四个别名，别只认一种
const pName  = p.contact_name || p.name || p.姓名 || '';
const pMsg   = p.message || p.content || p.body || p.remark || p.留言 || '';
const pEmail = p.contact_email || p.email || '';
const pPhone = p.contact_phone || p.phone || p.tel || '';
const pBudgetRaw = p.budget_raw ?? p.budget ?? p.预算 ?? '';
const text = ((pMsg||'') + ' ' + (pName||'')).toLowerCase();
const HIGH=['报价','多少钱','怎么收费','合同','签约','采购','下单','什么时候能开始','开发票','开票','预算','付款方式','quotation','pricing','how much','contract','invoice'];
const MID=['了解一下','咨询','对比','怎么样','有什么功能','看看','demo','演示','试用','案例'];
const SPAM=['seo服务','代开发票','刷单','加微信领','免费领取','博彩','贷款','点击链接','中奖','兼职日结'];
const IND={'制造':['工厂','产能','车间','制造','factory'],'电商':['店铺','sku','上架','电商','shopify'],'教育':['课程','学员','招生','培训'],'医疗':['诊所','门诊','患者','医院','clinic'],'法律':['律所','案件','诉讼','律师'],'房产':['楼盘','中介','房源','房产']};

const out = { payload: p };
out.fingerprint = j.fingerprint;

let spamHit = null;
for (const s of SPAM) if (text.includes(s)) { spamHit = '命中垃圾词：' + s; break; }
if (!spamHit && pEmail.split('@')[1] === 'mailinator.com') spamHit = '一次性邮箱';

// 从留言正文里抠预算。客户常常写在正文里而不是填框，
// 但要先剔掉手机号——否则"电话13800138000"会被当成 138 亿预算。
function budgetFromText(s0) {
  if (!s0) return null;
  let s = String(s0).replace(/[,¥￥]/g,'');
  s = s.replace(/1[3-9]\d{9}/g,' ').replace(/\b\d{7,}\b/g,' ')
       .replace(/\d{4}[-/年]\d{1,2}[-/月]\d{1,2}/g,' ')
       .replace(/[a-zA-Z]{0,3}\d{8,}[a-zA-Z0-9]*/g,' ');
  let m = s.match(/(?:预算|报价|费用|价格|价位|出价|准备|投入|能出|大概|最多|不超过|控制在|范围)[^0-9]{0,6}(\d+(?:\.\d+)?)\s*(万|w|千|k|元|块)?/i);
  if (m) {
    const num = parseFloat(m[1]);
    const u = (m[2]||'').toLowerCase();
    let mult = 1;
    if (u === '万' || u === 'w') mult = 10000;
    else if (u === '千' || u === 'k') mult = 1000;
    // 没单位：1–2 位数按千算（"预算15"→1.5万），"预算500"就是 500 元
    else if (!u) mult = num < 100 ? 1000 : 1;
    const n = Math.round(num * mult);
    if (n > 0) return n;
  }
  m = s.match(/(\d+(?:\.\d+)?)\s*(万|w|千|k)(?![a-z])/i);
  if (m) return Math.round(parseFloat(m[1]) * (['万','w'].includes(m[2].toLowerCase()) ? 10000 : 1000));
  return null;
}

// 预算：输入框优先，没有就从正文抠
let budget = null, budgetFromBody = false;
const br = String(pBudgetRaw).replace(/[,¥￥]/g,'').trim().toLowerCase();
if (br) {
  let mult = 1, t = br;
  if (/[万w]$/.test(br)) { mult = 10000; t = br.slice(0,-1); }
  else if (/k$/.test(br)) { mult = 1000; t = br.slice(0,-1); }
  const m = t.match(/\d+(\.\d+)?/);
  if (m) budget = Math.round(parseFloat(m[0]) * mult);
}
if (budget === null) {
  const bt = budgetFromText(pMsg);
  if (bt !== null) { budget = bt; budgetFromBody = true; }
}

if (spamHit) {
  out.ai_score = 0; out.ai_intent = 'spam'; out.ai_reason = spamHit; out.needs_review = false;
  out.budget_yuan = null; out.industry = null;
  return [{ json: out }];
}

let score = 0; const why = [];
const hitHighWords = HIGH.filter(w=>text.includes(w));
const hitHigh = hitHighWords.length > 0;
if (hitHigh) {
  // 命中 2 个以上强意向词 = 客户已经在问细节，不是路过问价
  score += 45 + (hitHighWords.length >= 2 ? 10 : 0);
  why.push('强意向词：' + hitHighWords.slice(0,3).join('、'));
}
else { const m = MID.filter(w=>text.includes(w)); if (m.length) { score += 30; why.push('中等意向：' + m.slice(0,2).join('、')); } }

if (budget !== null) {
  const src = budgetFromBody ? '（正文识别）' : '';
  if (budget >= 5000) { score += 25; why.push('预算明确 ≥5000 元' + src); }
  else if (budget >= 1000) { score += 10; why.push('预算 1000–5000 元' + src); }
  // 扣 25：否则"预算800 + 问报价"能靠强意向分冲到 warm
  else { score -= 25; why.push('预算过低（' + budget + ' 元），大概率不是目标客户' + src); }
}

// 行业是加分项不是门槛：命中 +15，未命中轻扣 5（行业不对成交率低，但不一票否决）
let industry = null;
for (const k of Object.keys(IND)) {
  if (IND[k].some(w=>text.includes(w))) { industry = k; score += 15; why.push('目标行业：'+k); break; }
}
// 有强意向时只轻扣 2：行业对不上但意图明确，那是要马上回的人
if (industry === null) { score += hitHigh ? -2 : -5; why.push('行业未命中（不在预设 6 个行业里）'); }

// 名/邮箱/电话/留言 四项；name+phone+message 三项齐的客户信息已够用
const filled = [pName, pEmail, pPhone, pMsg].filter(Boolean).length;
if (filled >= 3) { score += 10; why.push('联系方式齐全（' + filled + '/4 项）'); }
else if (filled <= 1) {
  // 强意向的线索没留电话是正常的，刚问报价的人不会一上来交底；
  // 中等意向（问了案例/功能）也算有明确需求，只轻扣；完全没意向词才重扣
  let pen;
  if (hitHigh) { pen = -5; why.push('还没留联系方式（但意向明确，优先回他）'); }
  else if (MID.some(w => text.includes(w))) { pen = -8; why.push('没留联系方式（在问了，值得追一句）'); }
  else { pen = -20; why.push('联系方式严重缺失'); }
  score += pen;
}
if ((pMsg||'').length < 10 && !hitHigh) { score -= 15; why.push('消息过短'); }

// 预算不到 5000 元绝不可能是高意向，硬封顶在 warm（65）
// 只靠扣分压不住：强意向 55 + 中意向…冲得到 70 以上
if (budget !== null && budget < 5000) score = Math.min(score, 65);

score = Math.max(0, Math.min(100, score));

out.budget_yuan = budget;
out.industry = industry;
out.ai_score = score;
out.ai_intent = score >= 70 ? 'hot' : (score >= 35 ? 'warm' : 'cold');
out.ai_reason = why.join('；') || '无匹配规则';
// 复核：卡在分级线边上 / 高分没预算 / 三条以上强意向词要人扫一眼
out.needs_review = (
  Math.abs(score-35)<=2 ||
  Math.abs(score-70)<=2 ||
  (score>=70 && budget===null) ||
  hitHighWords.length >= 3
);

// 路由：hot 给在手最少且行业对口的销售；垃圾直接归档
const reps = [
  {id:1, name:'销售A', active:2, industries:null},
  {id:2, name:'销售B', active:0, industries:['医疗','法律']},
  {id:3, name:'销售C', active:5, industries:['电商','制造']}
];
const j = $input.first().json;
const p = j.payload;
const out = { payload: p };
out.fingerprint = j.fingerprint;
out.budget_yuan = j.budget_yuan;
out.industry = j.industry;
out.ai_score = j.ai_score;
out.ai_intent = j.ai_intent;
out.ai_reason = j.ai_reason;
out.needs_review = j.needs_review;

if (j.ai_intent === 'spam') {
  out.owner_id = null; out.owner_name = null; out.status = 'junk';
  out.route_note = '垃圾线索，直接归档';
  return [{ json: out }];
}
let cands = reps.filter(r => !r.industries || j.industry === null || r.industries.includes(j.industry));
if (!cands.length) cands = reps;
cands.sort((a,b) => a.active - b.active);
const pick = cands[0];
out.owner_id = pick.id;
out.owner_name = pick.name;
out.status = j.ai_intent === 'hot' ? 'qualified' : 'new';
out.route_note = '分配给 ' + pick.name + '（在手 ' + pick.active + ' 条）';
return [{ json: out }];

// 汇总：这条就是能给客户看的日报。分钟数按每条人工 8 分钟估（可调）
// webhook 单条触发时 $input.all() 只有 1 条，所以"累计"只能放工作流静态数据
const j = $input.first().json;
const p = j.payload;
const intent = j.ai_intent;

const store = $getWorkflowStaticData('global');
if (!store.stats) store.stats = { total:0, hot:0, warm:0, cold:0, spam:0, auto_assigned:0, needs_review:0 };
const s = store.stats;
s.total += 1;
if (intent) s[intent] += 1;
if (j.owner_id) s.auto_assigned += 1;
if (j.needs_review) s.needs_review += 1;

const out = {};
out.generated_at = new Date().toISOString();
out.this_lead = { name: p.contact_name, email: p.contact_email, message: p.message,
                  score: j.ai_score, intent: intent, industry: j.industry,
                  budget_yuan: j.budget_yuan, owner: j.owner_name, status: j.status,
                  reason: j.ai_reason, needs_review: j.needs_review };
out.total = s.total;
out.hot = s.hot; out.warm = s.warm; out.cold = s.cold; out.spam = s.spam;
out.auto_assigned = s.auto_assigned;
out.needs_review = s.needs_review;
out.minutes_saved = (s.total - s.cold - s.spam) * 8;
out.ai_cost_yuan = 0;
out.note = '规则打分，未调用任何付费 API，成本 0；total 为累计值';
return [{ json: out }];

const p = $input.first().json.payload;
const out = { status: 'duplicate_skipped' };
out.message = '重复线索，已跳过';
out.received = p.message;
out.fingerprint = String($input.first().json.fingerprint ?? '');
return [{ json: out }];
